"    // Check if customer details are mandatory for PickUp / Delivery based on staff access levels
    const userAccess = getStaffPermissions()?.pos_access;
    const isPickup = orderType === 'PICKUP' && subOrderType !== 'DELIVERY';
    const isDelivery = orderType === 'DELIVERY' || (orderType === 'PICKUP' && subOrderType === 'DELIVERY');
    const isPickupMandatory = activeTrayTab !== 'PreOrder' && isPickup && userAccess?.Pickup?.customer_details_mandatory === true;
    const isDeliveryMandatory = activeTrayTab !== 'PreOrder' && isDelivery && userAccess?.Delivery?.customer_details_mandatory === true;

    if (isPickupMandatory || isDeliveryMandatory) {
      const modeLabel = isDeliveryMandatory ? "Delivery" : "PickUp";
      if (!customerName || !customerName.trim() || customerName.trim() === "POS Guest") {
        toast.warning(`Customer Name is mandatory for ${modeLabel} orders!`);
        return;
      }
      if (!customerPhone || !customerPhone.trim()) {
        toast.warning(`Customer Phone is mandatory for ${modeLabel} orders!`);
        return;
      }
    }"

